#define NOMINMAX
#include "../decompilation/cpp/ExplorerPresentation.h"
#include <fstream>
int main(){ExplorerModelPreview models;models.load(L".");   /* run from the repository root */int w=1000,h=500;BITMAPINFO info{};info.bmiHeader.biSize=40;info.bmiHeader.biWidth=w;info.bmiHeader.biHeight=-h;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels;auto dc=CreateCompatibleDC(nullptr);auto bitmap=CreateDIBSection(dc,&info,DIB_RGB_COLORS,&pixels,nullptr,0);SelectObject(dc,bitmap);RECT r{0,0,w,h};FillRect(dc,&r,(HBRUSH)GetStockObject(BLACK_BRUSH));unsigned types[]={8,16,20,21,23,7,11,12,6,19};SetBkMode(dc,TRANSPARENT);SetTextColor(dc,RGB(255,255,255));for(unsigned i=0;i<10;++i){int x=(i%5)*200,y=(i/5)*250;models.draw(dc,types[i],false,x,y+25,200,215,.8);auto label=std::to_wstring(types[i]);TextOutW(dc,x+10,y,label.c_str(),label.size());}GdiFlush();std::ofstream out("decompilation/reports/pickup-identification.bmp",std::ios::binary);BITMAPFILEHEADER file{0x4d42,DWORD(54+w*h*4),0,0,54};out.write((char*)&file,14);out.write((char*)&info.bmiHeader,40);out.write((char*)pixels,w*h*4);}
